let lastTrackingFetch=0;
function wireSidebar(){
 const desktop=window.matchMedia('(min-width:981px)'),shell=$('.shell'),button=$('#desktop-sidebar-toggle');
 let collapsed=false;try{collapsed=localStorage.getItem('dg.sidebar.collapsed')==='1'}catch(_){}
 const apply=()=>{const compact=desktop.matches&&collapsed;shell.classList.toggle('sidebar-collapsed',compact);document.body.classList.toggle('sidebar-compact',compact);button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg>';button.setAttribute('aria-expanded',String(!compact));button.setAttribute('aria-label',compact?'Expandir menu':'Recolher menu');button.title=compact?'Expandir menu':'Recolher menu';};
 button.onclick=()=>{collapsed=!collapsed;try{localStorage.setItem('dg.sidebar.collapsed',collapsed?'1':'0')}catch(_){}apply()};apply();
 if(wireSidebar.previous)wireSidebar.previous();const change=()=>apply();desktop.addEventListener('change',change);wireSidebar.previous=()=>desktop.removeEventListener('change',change);
 let tooltip=$('#sidebar-tooltip');if(!tooltip){tooltip=document.createElement('div');tooltip.id='sidebar-tooltip';tooltip.setAttribute('role','tooltip');tooltip.hidden=true;document.body.append(tooltip)}
 const hide=()=>tooltip.hidden=true;
 shell.querySelectorAll('[data-nav]').forEach(link=>{link.removeAttribute('title');const show=()=>{if(!shell.classList.contains('sidebar-collapsed'))return;tooltip.textContent=titles[link.dataset.nav];tooltip.hidden=false;const r=link.getBoundingClientRect();tooltip.style.left=($('.sidebar').getBoundingClientRect().right+16)+'px';tooltip.style.top=Math.max(8,Math.min(innerHeight-tooltip.offsetHeight-8,r.top+(r.height-tooltip.offsetHeight)/2))+'px';};link.onmouseenter=show;link.onfocus=show;link.onmouseleave=hide;link.onblur=hide;link.addEventListener('click',hide)});
 $('.nav-scroll').onscroll=hide;button.addEventListener('click',hide);
}
const roleDescriptions={Administrador:'Gerencia usuários e visualiza toda a operação.',Operação:'Programação, OC, documentos e cadastros operacionais.',Cadastro:'Pessoas, motoristas, veículos e cidades.',Captação:'Captação e programação dos agregados.','Torre de Controle':'Acompanha e atualiza as OCs.',Financeiro:'Valores, vale-pedágio, CIOT e aprovação de pagamentos.'};
function permissionEditor(d){
 const profiles=state.schema.usuarios.fields.find(f=>f.key==='perfis').options,all=state.schema.usuarios.fields.find(f=>f.key==='abas').options;
 return `<section class="form-section permission-profiles"><div class="section-heading"><span class="section-icon">${icon('pessoas')}</span><div><h3>Perfil da equipe</h3><p>Selecione um ou mais perfis. As abas padrão são combinadas.</p></div></div><div class="role-cards" data-field="perfis">${profiles.map(role=>`<label class="role-card"><input name="perfis" type="checkbox" value="${esc(role)}" ${(d.perfis||[]).includes(role)?'checked':''}><span class="role-symbol">${icon(role==='Financeiro'?'financeiro':role==='Cadastro'?'pessoas':role==='Captação'?'captacao':role==='Torre de Controle'?'tracking':role==='Administrador'?'configuracoes':'programacao')}</span><strong>${esc(role)}</strong><small>${esc(roleDescriptions[role])}</small><span class="role-check">${icon('check')}</span></label>`).join('')}</div></section><section class="form-section permission-matrix"><div class="section-heading"><span class="section-icon">${icon('configuracoes')}</span><div><h3>Acesso por aba</h3><p>Personalize o acesso e confira o resultado antes de salvar.</p></div><span id="permission-count" class="badge gray"></span></div><div class="permission-tools"><input id="permission-search" type="search" placeholder="Buscar uma aba…" aria-label="Pesquisar permissões"><button type="button" id="permissions-reset">Restaurar padrão dos perfis</button></div><div data-field="abas" class="permission-tab-rows"><table><thead><tr><th>Aba do sistema</th><th>Permissão</th><th>Acesso resultante</th></tr></thead><tbody>${all.map(tab=>`<tr data-permission-row="${esc(tab)}"><td>${icon(tab)} <strong>${esc(titles[tab]||tab)}</strong></td><td><select data-tab-permission="${esc(tab)}" aria-label="Acesso à aba ${esc(titles[tab]||tab)}"><option value="default">Padrão do perfil</option><option value="allow" ${(d.abas||[]).includes(tab)?'selected':''}>Permitir</option><option value="deny" ${(d.ocultar||[]).includes(tab)?'selected':''}>Bloquear</option></select></td><td data-access-result></td></tr>`).join('')}</tbody></table></div><div data-field="ocultar" class="permission-note">${icon('oc')} Aprovação de pagamentos e edição de descontos continuam exclusivas do perfil Financeiro, mesmo ao liberar uma aba. O Log é exclusivo do Administrador.</div></section>`;
}
const originalFormSections=formSections;
formSections=function(m,d){if(m!=='usuarios')return originalFormSections(m,d);const fields=state.schema.usuarios.fields.filter(f=>['nome','email','senha','status'].includes(f.key));return `<section class="form-section"><div class="section-heading"><span class="section-icon">${icon('motoristas')}</span><div><h3>Dados do usuário</h3><p>Identificação e acesso à conta.</p></div></div><div class="section-fields">${fields.map(f=>fieldHTML(f,d)).join('')}</div></section>`+permissionEditor(d)};
function wirePermissions(){
 const update=()=>{const roles=[...document.querySelectorAll('[name="perfis"]:checked')].map(x=>x.value),defaults=new Set(['dashboard','tracking','painel']);for(const role of roles)for(const tab of (state.profiles?.[role]||[]))defaults.add(tab);let count=0;document.querySelectorAll('[data-tab-permission]').forEach(select=>{const adminOnly=select.dataset.tabPermission==='auditoria'&&!roles.includes('Administrador');select.disabled=adminOnly;if(adminOnly)select.value='default';const enabled=!adminOnly&&(select.value==='allow'||select.value==='default'&&defaults.has(select.dataset.tabPermission));if(enabled)count++;select.closest('tr').querySelector('[data-access-result]').innerHTML=`<span class="access-state ${enabled?'allowed':'denied'}">${enabled?'Permitido':'Sem acesso'}</span>`});$('#permission-count').textContent=count+' abas permitidas';};
 document.querySelectorAll('[name="perfis"],[data-tab-permission]').forEach(el=>el.addEventListener('change',update));$('#permission-search').oninput=e=>{const term=normalizeText(e.target.value);document.querySelectorAll('[data-permission-row]').forEach(row=>row.hidden=!normalizeText(titles[row.dataset.permissionRow]).includes(term))};$('#permissions-reset').onclick=()=>{document.querySelectorAll('[data-tab-permission]').forEach(el=>el.value='default');update()};update();
}
