function wireV5Form(m,d,readOnly){
 if(m==='usuarios'){wirePermissions();if(readOnly)$('#record-form').querySelectorAll('.role-cards input,.permission-matrix input,.permission-matrix select,.permission-matrix button').forEach(el=>el.disabled=true)}
 if(['ciot','vale_pedagio'].includes(m)){for(const key of ['import-xml','import-doc'])$('#'+key)?.remove();if($('#f-oc')&&!readOnly)$('#f-oc').addEventListener('change',fillFromOC);if($('#emit-doc')){$('#emit-doc').textContent=m==='vale_pedagio'?'Solicitar compra':'Solicitar emissão';$('#emit-doc').addEventListener('click',async event=>{event.preventDefault();event.stopImmediatePropagation();const summary=m==='vale_pedagio'?`Solicitar compra do vale-pedágio?\nPlaca: ${$('#f-placa_visual')?.value||'—'}\nEixos: ${$('#f-numero_eixos')?.value||'—'}\nRota: ${$('#f-origem_cidade')?.value||'—'} → ${$('#f-destino_cidade')?.value||'—'}\nPagamento: Repom\n\nSem API configurada, a solicitação ficará pendente.`:'Solicitar emissão deste CIOT? Confira a carga e os pagamentos.';if(!await dgConfirm(summary))return;try{const result=await api('document-action',{module:m,id:d.id,action:'emit'});toast(result.message);closeEditorState();await navigate(current)}catch(e){$('#form-error').textContent=e.message}},true)}}
 if(m==='vale_pedagio'){
  const calculate=async()=>{try{const tracao=$('#f-tracao').value,carreta=$('#f-carreta').value;const vs=await api('vehicle-axles?tracao='+encodeURIComponent(tracao)+'&carreta='+encodeURIComponent(carreta));if(formContext?.module!==m||$('#f-tracao').value!==tracao||$('#f-carreta').value!==carreta)return;const traction=vs.tracao,trailer=vs.carreta;setField('placa_visual',traction?.placa||'');setField('eixos_tracao_visual',traction?.eixos||0);setField('eixos_carreta_visual',trailer?.eixos||0);const manual=$('#f-ajustar_eixos').value==='Sim';$('#f-numero_eixos').readOnly=readOnly||!manual;if(!manual)setField('numero_eixos',Number(traction?.eixos||0)+Number(trailer?.eixos||0));$('[data-field="eixos_ajuste_motivo"]').hidden=!manual;}catch(e){toast(e.message,true)}};
  if(!readOnly)['tracao','carreta','ajustar_eixos'].forEach(k=>$('#f-'+k).addEventListener('change',calculate));$('#f-numero_eixos').readOnly=readOnly||d.ajustar_eixos!=='Sim';$('[data-field="eixos_ajuste_motivo"]').hidden=d.ajustar_eixos!=='Sim';
 }
 if(m==='ciot'){if(!state.approve)for(const k of ['irrf','sest','senat','sest_senat','inss','iss','outros_tributos'])if($('#f-'+k))$('#f-'+k).disabled=true;const total=$('#f-total_viagem'),advance=$('#f-total_adiantamento');if(total&&advance&&!readOnly){const calculate=()=>{if(Number(total.value)>=Number(advance.value))setField('total_quitacao',Math.round((Number(total.value)-Number(advance.value))*100)/100)};total.addEventListener('input',calculate);advance.addEventListener('input',calculate)}}
 if(m==='oc'){
  const timeline=document.createElement('section');timeline.className='status-timeline';timeline.innerHTML='<h3>Histórico dos status</h3>'+Object.entries(d.status_datas||{}).map(([status,at])=>`<div>${badge(status)}<time>${esc(datefmt(at))}</time></div>`).join('');$('#oc-details').after(timeline);
  const sync=()=>{const stage=$('#f-status').value,key={'Aberta':'abertura_em','Embarque Autorizado':'autorizacao','Em Carregamento':'carregamento_real','Em Viagem':'saida_real','Chegada no Cliente':'chegada_real','Finalizada':'descarga_real'}[stage];document.querySelectorAll('.status-current-field').forEach(el=>el.classList.remove('status-current-field'));if(key)$(`[data-field="${key}"]`)?.classList.add('status-current-field')};$('#f-status').addEventListener('change',sync);sync();
 }
}
// Enter only advances editor fields; list searches and login keep normal submission.
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'){$('#sidebar-tooltip')?.setAttribute('hidden','');return}
 if(event.key!=='Enter'||event.ctrlKey||event.shiftKey||event.altKey||event.metaKey||event.isComposing)return;
 const target=event.target,form=target.closest?.('#record-form');if(!form||target.tagName==='TEXTAREA'||target.closest('.lookup')||target.tagName==='BUTTON'||['submit','button','reset','file','checkbox'].includes(target.type))return;
 const fields=[...form.querySelectorAll('input,select,textarea')].filter(el=>!el.disabled&&!el.readOnly&&el.type!=='hidden'&&el.type!=='checkbox'&&el.offsetParent!==null);const i=fields.indexOf(target);if(i<0)return;event.preventDefault();fields[i+1]?.focus();
});
const originalFillFromOC=fillFromOC;
fillFromOC=async function(){if(!['ciot','vale_pedagio'].includes(formContext?.module))return originalFillFromOC();const m=formContext.module,id=$('#f-oc').value;if(!id)return;try{
 const source=await api('oc-source?module='+m+'&id='+encodeURIComponent(id));if(formContext?.module!==m||$('#f-oc')?.value!==id)return;const oc=source.oc,p=source.programacao;
 const vals={motorista:p.motorista,tracao:p.tracao,carreta:p.carreta,carreta2:p.carreta2,produto:p.produto,peso_kg:p.peso,total_viagem:p.frete_agregado,total_operacao:p.frete_agregado,total_adiantamento:Math.round(Number(p.frete_agregado||0)*70)/100,total_quitacao:Math.round(Number(p.frete_agregado||0)*30)/100,pedagio:p.pedagio,inicio_viagem:oc.saida_real||p.carregamento,fim_viagem:p.eta_destino,documento_viagem:'OC-'+id,ncm:oc.ncm,inicio_vigencia:p.carregamento,fim_vigencia:p.eta_destino};
 for(const [k,v] of Object.entries(vals))if(v!==undefined&&$('#f-'+k))setField(k,v);
 for(const side of ['origem','destino']){const location=source.locais[side];if(m==='ciot')setField('cep_'+side,location.cep||'');else{setField(side+'_uf',location.uf||'');setField(side+'_cidade',location.cidade||'');setField(side+'_cep',location.cep||'');setField(side+'_codigo_ibge',location.ibge||'')}}if(m==='vale_pedagio')setField('cpf_cnpj_subcontratado',source.documento_subcontratado);
 if(m==='vale_pedagio')toast('Veículos e rota importados. Confira os eixos e a vigência.');else toast('Dados da OC importados. Confira NCM, peso em kg e pagamento.');
 }catch(e){toast(e.message,true)}};
