const referenceColumns=columns;
columns=function(m){const order={ocorrencias:['veiculo','tipo','data','responsavel','status','tempo_aberto','fechamento'],ciot:['numero','oc','motorista','tracao','identificador_cliente','ambiente','situacao_emissao','updated'],mdfe:['serie','numero','emissao','origem_cidade','destino_cidade','contratante','motorista','situacao_emissao','oc'],vale_pedagio:['documento','vigencia','trajeto','tracao','numero_eixos','meio_pagamento','valor','vpo_antt','situacao_operacao','updated']};if(!order[m])return referenceColumns(m);const synthetic={tempo_aberto:'Tempo em aberto',vigencia:'Vigência',trajeto:'Rota',updated:'Atualizado'};return order[m].map(k=>state.schema[m].fields.find(f=>f.key===k)||(synthetic[k]?{key:k,label:synthetic[k],type:'text'}:null)).filter(Boolean)};
const referenceCell=cell;
cell=function(f,r){if(f.key==='tempo_aberto'){if(!r.data)return '—';const delta=Math.max(0,new Date(r.fechamento||Date.now())-new Date(r.data));return Math.floor(delta/86400000)+'d '+Math.floor(delta/3600000)%24+'h'}if(f.key==='vigencia')return esc(String(r.inicio_vigencia||'').slice(0,10))+'<br><small>até '+esc(String(r.fim_vigencia||'').slice(0,10))+'</small>';if(f.key==='trajeto')return esc(r.origem_cidade||'—')+' / '+esc(r.origem_uf||'')+'<br><small>→ '+esc(r.destino_cidade||'—')+' / '+esc(r.destino_uf||'')+'</small>';if(f.key==='updated')return esc(String(r.updated||'').replace('T',' ').slice(0,16));return referenceCell(f,r)};
const referenceFilters=listFilterHTML;
listFilterHTML=function(m){const inp=(k,l,t='text')=>`<label class="filter-field"><span>${l}</span><input name="${k}" type="${t}"></label>`,sel=(k,l,opts)=>`<label class="filter-field"><span>${l}</span><select name="${k}"><option value="">Todos</option>${opts.map(o=>`<option value="${esc(Array.isArray(o)?o[0]:o)}">${esc(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select></label>`;if(m==='ocorrencias')return inp('placa','Placa')+sel('tipo','Tipo de problema',state.schema[m].fields.find(f=>f.key==='tipo').options.filter(Boolean))+sel('status','Status',['Aberta','Em tratamento','Resolvida'])+sel('responsavel','Responsável',(state.refs.usuarios||[]).map(u=>[u.id,u.nome]))+inp('de','Ocorrência de','date')+inp('ate','Até','date');if(m==='ciot')return sel('situacao','Situação',['Rascunho','Aguardando configuração','Em processamento','Em viagem','Encerrado','Cancelado','Erro'])+inp('oc','Número da OC');return referenceFilters(m)};
const referenceFilter=filterList;
filterList=function(m,data,f={}){if(m==='ocorrencias'){if(f.responsavel)data=data.filter(r=>String(r.responsavel)===String(f.responsavel));if(f.placa)data=data.filter(r=>plateMatch(ref('veiculos',r.veiculo),f.placa));return referenceFilter(m,data,{...f,placa:''})}return referenceFilter(m,data,f)};
const referenceMetrics=listMetricsHTML;
listMetricsHTML=function(m,data){if(m!=='ocorrencias')return referenceMetrics(m,data);const cards=[['Abertas',data.filter(r=>r.status!=='Resolvida').length],['Resolvidas',data.filter(r=>r.status==='Resolvida').length],['Abertas há mais de 7 dias',data.filter(r=>r.status!=='Resolvida'&&r.data&&Date.now()-new Date(r.data)>604800000).length]];return `<div class="list-metrics metrics-3 occurrence-metrics">${cards.map(([l,n])=>`<div class="list-metric"><span>${l}</span><strong>${n}</strong></div>`).join('')}</div>`};
const referenceWireForm=wireV5Form;
wireV5Form=function(m,d,readOnly){referenceWireForm(m,d,readOnly);if(['rotas','ocorrencias','ciot','vale_pedagio','cte','mdfe'].includes(m))$('.editor-page')?.classList.add('reference-editor');if(m==='ocorrencias'){const status=$('#f-status'),solution=$('#f-solucao'),close=$('#f-fechamento');const update=()=>{const resolved=status?.value==='Resolvida';if(solution)solution.required=resolved;if(close)close.setAttribute('aria-required',String(resolved));};status?.addEventListener('change',update);update()}if(m==='rotas')wireRouteEditor(readOnly)};
function wireRouteEditor(readOnly){const input=$('#f-ufs');if(!input)return;input.type='hidden';const panel=document.createElement('div');panel.className='route-sequence';input.after(panel);const preview=document.createElement('div');preview.className='route-preview';panel.after(preview);const render=()=>{const values=input.value.split(',').map(v=>v.trim()).filter(Boolean),ufs=state.schema.rotas.fields.find(f=>f.key==='uf_origem').options.filter(Boolean);panel.innerHTML='<div class="route-sequence-heading"><strong>UFs intermediárias</strong><button type="button" data-route-add '+(readOnly?'disabled':'')+'>+ Adicionar UF</button></div>'+(!values.length?'<div class="route-empty">Nenhuma UF intermediária adicionada.</div>':values.map((v,i)=>`<div class="route-state"><span>${i+1}</span><select data-route-index="${i}" ${readOnly?'disabled':''}>${ufs.map(u=>`<option ${u===v?'selected':''}>${u}</option>`).join('')}</select><button type="button" data-route-up="${i}" ${readOnly||i===0?'disabled':''} aria-label="Mover UF para cima">↑</button><button type="button" data-route-remove="${i}" ${readOnly?'disabled':''}>Remover</button></div>`).join(''));const save=()=>{input.value=values.join(', ');render()};panel.querySelector('[data-route-add]').onclick=()=>{values.push(ufs.find(v=>!values.includes(v)&&v!==$('#f-uf_origem')?.value&&v!==$('#f-uf_destino')?.value)||'SP');save()};panel.querySelectorAll('[data-route-index]').forEach(el=>el.onchange=()=>{values[Number(el.dataset.routeIndex)]=el.value;save()});panel.querySelectorAll('[data-route-remove]').forEach(el=>el.onclick=()=>{values.splice(Number(el.dataset.routeRemove),1);save()});panel.querySelectorAll('[data-route-up]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.routeUp);[values[i-1],values[i]]=[values[i],values[i-1]];save()});preview.textContent=[$('#f-uf_origem')?.value,...values,$('#f-uf_destino')?.value].filter(Boolean).join(' → ')||'Selecione a origem, o percurso e o destino.';};for(const k of ['uf_origem','uf_destino'])$('#f-'+k)?.addEventListener('change',render);render()}

const referenceRow=rowHTML;
const transportDocumentColumns=[['tipo','Tipo'],['numero','Número'],['serie','Série'],['emissao','Emissão','date'],['cfop','CFOP'],['valor','Valor','number'],['base','B.C.','number'],['icms','ICMS','number'],['base_st','B.C. ST','number'],['icms_st','ICMS ST','number'],['chave','Chave'],['municipio','Município'],['peso','Peso','number']];
rowHTML=function(row,key='documentos'){if(key!=='documentos'||!['cte','mdfe'].includes(formContext?.module))return referenceRow(row);let value;if(typeof row==='string')value={chave:row};else if(Array.isArray(row))value={chave:row[0]||'',municipio:row[1]||'',valor:row[2]||'',peso:row[3]||'',dados_anteriores:row.slice(4).join('; ')};else value=row||{};return `<div class="transport-document-row"><div class="transport-document-fields">${transportDocumentColumns.map(([k,l,t])=>`<label><span>${l}</span><input data-doc-cell="${k}" type="${t||'text'}" ${t==='number'?'min="0" step="any"':''} value="${esc(value[k]??'')}"></label>`).join('')}${value.dados_anteriores?`<label><span>Dados anteriores</span><input data-doc-cell="dados_anteriores" value="${esc(value.dados_anteriores)}"></label>`:''}</div><button type="button" class="small" data-remove-row>Remover documento</button></div>`};
const referenceReadForm=readForm;
readForm=function(){const data=referenceReadForm();if(['cte','mdfe'].includes(formContext.module))data.documentos=[...document.querySelectorAll('[data-rows="documentos"] .transport-document-row')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-doc-cell]')].map(input=>[input.dataset.docCell,input.value]))).filter(row=>Object.values(row).some(Boolean));return data};
const documentFormWire=wireV5Form;
wireV5Form=function(m,d,readOnly){documentFormWire(m,d,readOnly);if(['cte','mdfe','ciot','vale_pedagio','rotas','ocorrencias'].includes(m))$('.editor-page')?.setAttribute('data-reference-module',m);if(['cte','mdfe'].includes(m)){const docs=$('[data-rows="documentos"]'),imports=$('.document-imports');if(docs&&imports){docs.before(imports);if(readOnly)imports.querySelectorAll('button').forEach(button=>button.disabled=true);const add=docs.querySelector('[data-add-row]');if(add)add.innerHTML=icon('plus')+(m==='mdfe'?' Adicionar CT-e / NF-e':' Adicionar documento');if(!docs.querySelector('.transport-document-row')){const empty=document.createElement('p');empty.className='document-empty';empty.textContent='Nenhum documento adicionado.';docs.prepend(empty);add?.addEventListener('click',()=>empty.remove())}}}if(m==='ciot'){const row=$('[data-add-row="pagamentos"]');if(row)row.innerHTML=icon('plus')+' Adicionar pagamento'}if(m==='ocorrencias'&&!d.id&&!readOnly)setField('responsavel',state.user.id)};

const v14Columns=columns;
columns=function(m){const orders={pessoas:['nome','documento','cidade','telefone','email','status'],motoristas:['nome','cpf','telefone','cidade','cnh','cnh_categoria','cnh_validade','cnh_situacao','perfil_securitario','forms','spx','status'],veiculos:['placa','tipo','marca','modelo','carroceria','cor','ano_modelo','proprietario','cidade','motorista_vinculado','status'],cidades:['nome','uf','estado','pais','ibge'],captacao:['data','nome','telefone','implemento','rotas','ultimo_contato','responsavel','meio','status'],programacao:['lh_trip','carregamento','cliente','origem','destino','motorista','status','oc_id','mdfe_id'],oc:['data_oc','programacao','tomador','origem','destino','motorista','tracao','status','mdfe_id']};if(!orders[m])return v14Columns(m);const synthetic={cnh_situacao:'Situação CNH',motorista_vinculado:'Motorista',oc_id:'OC',mdfe_id:'MDF-e'};return orders[m].map(k=>{const f=state.schema[m].fields.find(f=>f.key===k);return f?{...f,label:({carregamento:'Data - hora coleta',responsavel:'Captador',ano_modelo:'Ano',tracao:'Cavalo'})[k]||f.label}:synthetic[k]?{key:k,label:synthetic[k],type:'text'}:null}).filter(Boolean)};
const v14Cell=cell;
function linkedBadge(module,id,label){return id?`<button type="button" class="document-link" data-open-linked="${module}" data-record-id="${esc(id)}" ${state.tabs.includes(module)?'':'disabled'}>${icon('oc')} ${esc(label)}</button>`:'—'}
cell=function(f,r){if(f.key==='oc_id')return linkedBadge('oc',r.oc_id,'OC #'+r.oc_id);if(f.key==='mdfe_id')return linkedBadge('mdfe',r.mdfe_id,'MDF-e '+(r.mdfe_numero||'#'+r.mdfe_id));if(current==='oc'&&f.key==='programacao')return `<button type="button" class="document-link program-link" data-open-linked="programacao" data-record-id="${esc(r.programacao)}" ${state.tabs.includes('programacao')?'':'disabled'}><span>${icon('programacao')} ${esc(datefmt(r.programacao_horario))}</span><small>${esc(r.programacao_lh||'#'+r.programacao)}</small></button>`;if(f.key==='cnh_situacao'){const v=r.cnh_validade;return badge(!v?'Não informada':v.slice(0,10)<localDay()?'Vencida':'OK')}if(['perfil_securitario','forms','spx'].includes(f.key))return r[f.key]?`<span class="boolean-label ${r[f.key]==='Sim'?'yes':'no'}">${esc(r[f.key].toUpperCase())}</span>`:'—';if(f.key==='cidade'){const item=state.refs.cidades?.find(v=>String(v.id)===String(r.cidade));return esc(item?item.nome+(item.uf?' / '+item.uf:''):r.cidade?'#'+r.cidade:'—')}if(current==='oc'&&['origem','destino'].includes(f.key)){const item=state.refs.pessoas?.find(v=>String(v.id)===String(r[f.key])),city=state.refs.cidades?.find(c=>String(c.id)===String(item?.cidade));return esc(ref('pessoas',r[f.key]))+(city?'<small class="location-note">'+esc(city.nome+(city.uf?' - '+city.uf:''))+'</small>':'')}if(f.key==='motorista')return `<span class="driver-name">${v14Cell(f,r)}</span>`;return v14Cell(f,r)};
const v14FilterHTML=listFilterHTML;
listFilterHTML=function(m){if(m!=='cidades')return v14FilterHTML(m);const ufs=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];return `<label class="filter-field"><span>Pesquisar</span><input name="q" placeholder="Cidade, UF, estado, país ou IBGE…"></label><label class="filter-field"><span>Cidade</span><input name="nome" placeholder="Nome da cidade"></label><label class="filter-field"><span>UF</span><select name="uf"><option value="">Todas</option>${ufs.map(u=>`<option>${u}</option>`).join('')}</select></label><label class="filter-field"><span>Por página</span><select name="por_pagina">${[10,25,50,100,200].map(n=>`<option ${n===100?'selected':''}>${n}</option>`).join('')}</select></label>`};
let listSort=null;
const v14Filter=filterList;
filterList=function(m,data,f={}){let result=v14Filter(m,data,f);if(f.uf)result=result.filter(r=>String(r.uf||'').toUpperCase()===f.uf);if(listSort?.module===m){const {key,descending}=listSort,field=columns(m).find(f=>f.key===key),value=r=>field?.type==='ref'?ref(field.options[0],r[key]):r[key];result=result.slice().sort((a,b)=>String(value(a)??'').localeCompare(String(value(b)??''),'pt-BR',{numeric:true})*(descending?-1:1))}return result};
const v14TableRows=tableRows;
tableRows=function(){v14TableRows();const table=$('#list-table table');if(!table)return;table.classList.add('reference-table');table.setAttribute('data-table-module',current);const headings=[...table.querySelectorAll('thead th')],cols=columns(current);headings.forEach((th,i)=>{if(i===headings.length-1)return;const key=i===0?'id':cols[i-1]?.key;if(!key)return;const title=th.textContent;th.setAttribute('aria-sort',listSort?.module===current&&listSort.key===key?(listSort.descending?'descending':'ascending'):'none');th.innerHTML=`<button class="column-sort" type="button">${esc(title)} <span aria-hidden="true">↕</span></button>`;th.querySelector('button').onclick=()=>{listSort={module:current,key,descending:listSort?.module===current&&listSort.key===key?!listSort.descending:false};listPage=1;tableRows()}});if(current==='programacao'){table.querySelectorAll('tr').forEach(tr=>tr.firstElementChild?.remove())}table.querySelectorAll('[data-open-linked]').forEach(b=>b.onclick=()=>openLinkedRecord(b.dataset.openLinked,Number(b.dataset.recordId)));if(current==='oc')table.querySelectorAll('[data-edit]').forEach(b=>{const pdf=document.createElement('button');pdf.className='small pdf-action';pdf.type='button';pdf.title='Imprimir OC / PDF';pdf.setAttribute('aria-label','Imprimir OC '+b.dataset.edit);pdf.innerHTML=icon('download');pdf.onclick=()=>window.open('/api/print?id='+Number(b.dataset.edit),'_blank','noopener');b.before(pdf)});const title=$('.list-page .cardhead h3');if(title)title.textContent=({pessoas:'Pessoas cadastradas',motoristas:'Motoristas cadastrados',veiculos:'Veículos cadastrados',cidades:'Cidades cadastradas',captacao:'Motoristas captados',programacao:'Programações',oc:'OCs cadastradas'})[current]||titles[current];if(['pessoas','motoristas','veiculos','cidades','captacao'].includes(current))table.querySelectorAll('[data-edit]').forEach(b=>{const trash=document.createElement('button');trash.className='small delete-action';trash.type='button';trash.title='Excluir cadastro';trash.setAttribute('aria-label','Excluir cadastro '+b.dataset.edit);trash.innerHTML=icon('close');trash.onclick=()=>deleteRecord(current,Number(b.dataset.edit));b.after(trash)})};
async function openLinkedRecord(module,id){try{if(!state.tabs.includes(module))throw Error('Seu perfil não permite acessar esta aba.');const records=await api('records?module='+module),record=records.find(r=>r.id===id);if(!record)throw Error('Registro não encontrado.');await edit(record,module)}catch(e){toast(e.message,true)}}
async function deleteRecord(module,id){if(!await dgConfirm('Excluir este cadastro da lista? A exclusão será registrada no Log. Cadastros vinculados a outros registros não podem ser excluídos.'))return;try{await api('delete-record',{module,id});toast('Cadastro excluído.');await refreshRefs();await navigate(module)}catch(e){toast(e.message,true)}}

function dailyOcCounts(list,now=new Date()){const today=new Date(now.getFullYear(),now.getMonth(),now.getDate(),12);return Array.from({length:14},(_,i)=>{const date=new Date(today);date.setDate(date.getDate()-13+i);const day=localDay(date);return {day,label:date.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}),count:list.filter(o=>String(o.data_oc||o.created||'').slice(0,10)===day).length}})}
function dashboardView(){const active=activeTrips(),moving=operations.oc.filter(o=>o.status==='Em Viagem'),finished=operations.oc.filter(o=>o.status==='Finalizada'),missing=active.filter(p=>!p.motorista),days=dailyOcCounts(operations.oc),max=Math.max(1,...days.map(d=>d.count)),total=days.reduce((n,d)=>n+d.count,0),manifests=(operations.mdfe||[]).filter(d=>d.ambiente==='Produção'&&d.situacao_emissao==='Autorizado'&&!d.encerramento);const shortcuts=[['pessoas','Cadastrar Pessoa','Novo cadastro','pessoas'],['motoristas','Cadastrar Motorista','Novo cadastro','motoristas'],['veiculos','Cadastrar Veículo','Novo cadastro','veiculos'],['programacao','Nova OC','Criar pela Programação','oc'],['mdfe','MDF-e','Abrir módulo','oc']].filter(([m])=>state.tabs.includes(m));$('#view').innerHTML=`<div class="content dashboard-reference"><div class="dashboard-heading"><div><h2>Dashboard</h2><p class="muted">Acesso rápido e acompanhamento das operações de transporte.</p></div><small>Atualizado em ${esc(datefmt(operations.at||new Date().toISOString()))}</small></div><section class="card dashboard-shortcuts"><div class="cardhead"><div>${icon('dashboard')}<h3>Atalhos rápidos</h3><p>Acesse diretamente as rotinas mais utilizadas.</p></div></div><div class="quick-shortcuts">${shortcuts.map(([m,l,n,i])=>`<button type="button" data-quick-module="${m}"><span class="quick-icon">${icon(i)}</span><span><strong>${l}</strong><small>${n}</small></span></button>`).join('')||'<p>Seus atalhos aparecem conforme as permissões de acesso.</p>'}</div></section><div class="dashboard-grid"><section class="card"><div class="cardhead"><div><h3>Ordens de carregamento por dia</h3><p>Movimentação registrada nos últimos 14 dias.</p></div></div><div class="daily-chart-summary"><strong>${total}</strong><small>ordens no período</small></div><div class="daily-chart" role="img" aria-label="${esc(days.map(d=>d.label+': '+d.count+' OC(s)').join('; '))}">${days.map(d=>`<div class="daily-column"><strong>${d.count}</strong><div class="daily-bar-space"><div class="daily-bar" style="height:${Math.round(d.count/max*180)}px"></div></div><span>${d.label}</span></div>`).join('')}</div></section><section class="card"><div class="cardhead"><div><h3>MDF-e autorizados não encerrados</h3><p>Documentos de produção aguardando encerramento.</p></div>${state.tabs.includes('mdfe')?'<button class="text-action" data-dashboard-mdfe>Ver todos →</button>':''}</div><div class="tablewrap dashboard-documents">${manifests.length?`<table><thead><tr><th>MDF-e</th><th>Emissão</th><th>Origem</th><th>Destino</th><th>Protocolo</th><th>Status</th></tr></thead><tbody>${manifests.slice(0,10).map(d=>`<tr><td>${linkedBadge('mdfe',d.id,d.numero||'#'+d.id)}<small class="location-note">Série ${esc(d.serie||'—')}</small></td><td>${esc(datefmt(d.emissao))}</td><td>${esc(ref('cidades',d.origem_cidade))}</td><td>${esc(ref('cidades',d.destino_cidade))}</td><td>${esc(d.protocolo||'—')}</td><td>${badge(d.situacao_emissao)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><p>Nenhum MDF-e autorizado aguardando encerramento.</p></div>'}</div></section></div><div class="metrics">${[['Viagens abertas',active.length],['Em viagem',moving.length],['Sem motorista',missing.length],['Finalizadas',finished.length]].map(([l,n])=>`<div class="metric"><small>${l}</small><div class="value">${n}</div></div>`).join('')}</div></div>`;document.querySelectorAll('[data-quick-module]').forEach(b=>b.onclick=()=>b.dataset.quickModule==='mdfe'?navigate('mdfe'):edit({},b.dataset.quickModule));$('[data-dashboard-mdfe]')?.addEventListener('click',()=>navigate('mdfe'));document.querySelectorAll('[data-open-linked]').forEach(b=>b.onclick=()=>openLinkedRecord(b.dataset.openLinked,Number(b.dataset.recordId)))}
const trackingReferenceView=trackingView;
trackingView=function(){trackingReferenceView();$('.tracking-page')?.classList.add('tracking-reference');const list=$('.vehicle-list');if(list){const heading=document.createElement('div');heading.className='vehicle-list-heading';heading.innerHTML='<strong>Veículos monitorados</strong><small>Posições das viagens em andamento</small>';list.prepend(heading)}const legend=document.createElement('div');legend.className='tracking-legend';legend.innerHTML='<span><i class="fresh"></i> Até 10 min</span><span><i class="attention"></i> 10 a 30 min</span><span><i class="stale"></i> Acima de 30 min</span>';$('#tracking-map')?.append(legend)};

function trashIcon(){return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7M14 10v7"/></svg>'}
function dgAskReason(title){return new Promise(resolve=>{const previous=document.activeElement,dialog=document.createElement('dialog');dialog.className='dg-confirm';dialog.innerHTML=`<form><div class="dg-confirm-body"><h2>${esc(title)}</h2><p>Informe o motivo. A viagem continuará registrada no sistema.</p><label for="cancel-reason">Motivo do cancelamento</label><textarea id="cancel-reason" required rows="4" placeholder="Descreva o motivo…"></textarea></div><div class="dg-confirm-actions"><button type="button" data-back>Voltar</button><button type="submit" class="primary">Confirmar cancelamento</button></div></form>`;document.body.append(dialog);const finish=value=>{dialog.close();dialog.remove();previous?.focus?.();resolve(value)};dialog.addEventListener('cancel',event=>{event.preventDefault();finish(null)});dialog.querySelector('[data-back]').onclick=()=>finish(null);dialog.querySelector('form').onsubmit=event=>{event.preventDefault();const text=dialog.querySelector('textarea').value.trim();if(!text){dialog.querySelector('textarea').setCustomValidity('Informe o motivo do cancelamento.');dialog.querySelector('textarea').reportValidity();return}finish(text)};dialog.querySelector('textarea').oninput=event=>event.target.setCustomValidity('');dialog.showModal();dialog.querySelector('textarea').focus()})}
async function cancelListedTrip(programId){const reason=await dgAskReason('Cancelar viagem');if(!reason)return;try{await api('cancel-trip',{id:programId,motivo:reason});toast('Viagem cancelada.');await refreshRefs();await navigate(current)}catch(error){toast(error.message,true)}}
const actionsTableRows=tableRows;
tableRows=function(){actionsTableRows();document.querySelectorAll('.delete-action').forEach(button=>button.innerHTML=trashIcon());if(!['programacao','oc'].includes(current)||!state.tabs.includes('programacao'))return;document.querySelectorAll('#list-table [data-edit]').forEach(b=>{const row=rows.find(r=>r.id===Number(b.dataset.edit));if(!row||['Finalizada','Cancelada'].includes(row.status))return;const button=document.createElement('button');button.type='button';button.className='small delete-action';button.title='Cancelar viagem';button.setAttribute('aria-label','Cancelar viagem '+row.id);button.innerHTML=trashIcon();button.onclick=()=>cancelListedTrip(current==='oc'?row.programacao:row.id);b.after(button)})};
const restoreLogRow=logRowHTML;
logRowHTML=function(event){const html=restoreLogRow(event);if(event.action!=='Excluir cadastro'||!['pessoas','motoristas','veiculos','cidades','captacao'].includes(event.module))return html;return html.replace('</td></tr>',`<button class="small" data-restore-module="${esc(event.module)}" data-restore-id="${esc(event.record_id)}">Restaurar cadastro</button></td></tr>`)};
const restoreAuditView=auditView;
auditView=async function(){await restoreAuditView();document.querySelectorAll('[data-restore-module]').forEach(button=>button.onclick=async()=>{try{await api('restore-record',{module:button.dataset.restoreModule,id:Number(button.dataset.restoreId)});await refreshRefs();toast('Cadastro restaurado.');await auditView()}catch(e){toast(e.message,true)}})};

const dedicatedSlaTrip=slaTripHTML;
slaTripHTML=function(r){const html=dedicatedSlaTrip(r);if(current!=='sla')return html;const buttons=state.tabs.includes('programacao')&&!['Cancelada','Finalizada'].includes(r.status_viagem)?`<button type="button" data-sla-settings="programacao" data-sla-record="${r.programacao}">Janelas e tolerâncias</button>`:'';const reports=r.oc&&state.tabs.includes('oc')&&!['Cancelada','Finalizada'].includes(r.status_viagem)?`<button type="button" data-sla-settings="oc" data-sla-record="${r.oc}">Previsões e reportes</button>`:'';return html.replace('</article>',`<div class="sla-settings-actions">${buttons}${reports}</div></article>`)};
const dedicatedSlaActions=wireSlaActions;
wireSlaActions=function(){dedicatedSlaActions();document.querySelectorAll('[data-sla-settings]').forEach(b=>b.onclick=()=>editDedicatedSla(b.dataset.slaSettings,Number(b.dataset.slaRecord)))};
async function editDedicatedSla(module,id){try{if(current!=='sla'||!state.tabs.includes(module))return;const records=await api('records?module='+module),record=records.find(r=>r.id===id);if(!record)throw Error('Registro não encontrado.');const fields=state.schema[module].fields.filter(f=>f.key.startsWith('sla_')&&f.type!=='readonly');if(!fields.length)throw Error('Nenhum campo de controle disponível.');const dialog=document.createElement('dialog');dialog.id='sla-settings-dialog';dialog.className='sla-settings-dialog';dialog.innerHTML=`<form><div class="section-heading"><div><h3>${module==='oc'?'Previsões e reportes da OC':'Janelas e tolerâncias da viagem'}</h3><p>${module==='oc'?'Os horários reais de carregamento, saída, chegada e descarga continuam na OC.':'Sem uma janela específica, o controle usa coleta e ETA previstos na Programação.'}</p></div></div><div class="section-fields">${fields.map(f=>fieldHTML(f,record)).join('')}</div><p class="error" id="sla-settings-error" role="alert"></p><div class="dg-confirm-actions"><button type="button" data-sla-settings-back>Cancelar</button><button class="primary" type="submit">Salvar controle</button></div></form>`;document.body.append(dialog);const close=()=>{dialog.close();dialog.remove()};dialog.querySelector('[data-sla-settings-back]').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close()});wireDateTimes();dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=dialog.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(fields.map(f=>{const value=dialog.querySelector('#f-'+f.key)?.value||'';return [f.key,['number','money'].includes(f.type)&&value!==''?Number(value):value]}));await api('records',{module,id,version:record.version,data});close();toast('Controle atualizado.');await navigate('sla')}catch(error){dialog.querySelector('#sla-settings-error').textContent=error.message;button.disabled=false}};dialog.showModal();dialog.querySelector('input:not([type=hidden]),select,textarea')?.focus()}catch(e){toast(e.message,true)}}

boot();
setInterval(()=>{if(current!=='tracking'||formContext)return;const label=$('#tracking-countdown');if(label){const seconds=Math.max(0,Math.ceil((300000-Date.now()+lastTrackingFetch)/1000));label.textContent='Próxima atualização em '+Math.floor(seconds/60)+'m '+String(seconds%60).padStart(2,'0')+'s'}const age=v=>v.posicao_em?Math.max(0,(Date.now()-new Date(v.posicao_em))/60000):Infinity;document.querySelectorAll('[data-vehicle]').forEach(card=>{const v=operations?.veiculos.find(v=>v.id===Number(card.dataset.vehicle)),dot=card.querySelector('.position-dot');if(dot&&v)dot.className='position-dot '+(age(v)<=10?'fresh':age(v)<=30?'attention':'stale')})},1000);
let documentGridBusy=false;
setInterval(async()=>{if(!state||formContext||document.hidden||!['ciot','vale_pedagio'].includes(current)||documentGridBusy||$('#list-table')?.contains(document.activeElement))return;const module=current;documentGridBusy=true;try{const updated=await api('records?module='+module);if(current===module&&!formContext){rows=updated;tableRows()}}catch(_){}finally{documentGridBusy=false}},10000);

window.addEventListener('resize',()=>{const tooltip=$('#sidebar-tooltip');if(tooltip)tooltip.hidden=true});
setInterval(()=>{if(current!=='tracking'||formContext||!operations)return;const active=operations.oc.filter(o=>['Em Carregamento','Em Viagem','Chegada no Cliente'].includes(o.status)),progs=operations.programacao.filter(p=>active.some(o=>o.programacao===p.id)),located=operations.veiculos.filter(v=>progs.some(p=>p.tracao===v.id)&&validPosition(v)),age=v=>v.posicao_em?Math.max(0,(Date.now()-new Date(v.posicao_em))/60000):Infinity;const counts=[located.length,located.filter(v=>age(v)<=10).length,located.filter(v=>age(v)>10&&age(v)<=30).length,located.filter(v=>age(v)>30).length];document.querySelectorAll('.tracking-metrics strong').forEach((el,i)=>el.textContent=counts[i]);for(const {p,marker} of DGMap.active?.markers||[]){const element=marker.getElement()?.querySelector('.dg-map-marker');if(element)element.className='dg-map-marker '+(age(p)<=10?'fresh':age(p)<=30?'attention':'stale')}},60000);
